using System;using System.IO;using System.Reflection;using System.Text;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine;using UnityEngine.Animations;using UnityEngine.Playables;
namespace StarterAssets.CQCEditorTools {public static class PreviewDownloadedSword {
public static void Apply(){
var original=GameObject.Find("PlayerArmature");var preview=new PreviewRenderUtility();PlayableGraph graph=default;
try{var clone=UnityEngine.Object.Instantiate(original);clone.transform.SetPositionAndRotation(Vector3.zero,Quaternion.identity);foreach(var b in clone.GetComponentsInChildren<MonoBehaviour>())b.enabled=false;foreach(var c in clone.GetComponentsInChildren<Collider>())c.enabled=false;preview.AddSingleGO(clone);
var animator=clone.GetComponent<Animator>();var weapon=clone.GetComponent<WeaponController>();animator.applyRootMotion=false;animator.cullingMode=AnimatorCullingMode.AlwaysAnimate;animator.Rebind();var hand=animator.GetBoneTransform(HumanBodyBones.RightHand);var model=UnityEngine.Object.Instantiate(weapon.SwordModelPrefab,hand,false);model.transform.localScale=Vector3.one;
const BindingFlags flags=BindingFlags.Instance|BindingFlags.NonPublic;typeof(WeaponController).GetField("animator",flags).SetValue(weapon,animator);typeof(WeaponController).GetField("sword",flags).SetValue(weapon,model);var fit=typeof(WeaponController).GetMethod("FitGrip",flags);object[] args={model,HumanBodyBones.RightHand,HumanBodyBones.RightIndexProximal,HumanBodyBones.RightLittleProximal,weapon.SwordGripOffset,weapon.SwordGripAdjustment};
graph=PlayableGraph.Create("Downloaded combat preview");graph.SetTimeUpdateMode(DirectorUpdateMode.Manual);var controller=AnimatorControllerPlayable.Create(graph,animator.runtimeAnimatorController);controller.SetBool("Grounded",true);controller.SetFloat("MotionSpeed",1);var layers=AnimationLayerMixerPlayable.Create(graph,2);graph.Connect(controller,0,layers,0);layers.SetInputWeight(0,1);var output=AnimationPlayableOutput.Create(graph,"Player",animator);output.SetSourcePlayable(layers);graph.Play();for(int i=0;i<60;i++)graph.Evaluate(1f/60);typeof(WeaponController).GetMethod("CalibrateStableSwordGrip",flags).Invoke(weapon,null);
var mask=new AvatarMask();for(int i=0;i<(int)AvatarMaskBodyPart.LastBodyPart;i++)mask.SetHumanoidBodyPartActive((AvatarMaskBodyPart)i,i!=(int)AvatarMaskBodyPart.Root&&i!=(int)AvatarMaskBodyPart.LeftLeg&&i!=(int)AvatarMaskBodyPart.RightLeg&&i!=(int)AvatarMaskBodyPart.LeftFootIK&&i!=(int)AvatarMaskBodyPart.RightFootIK);
var set=Resources.Load<SwordAnimationSet>("WeaponAnimations/DownloadedSword/DownloadedSword");var report=new StringBuilder();Directory.CreateDirectory("Logs");
preview.camera.transform.position=new Vector3(2.8f,2.1f,4.2f);preview.camera.transform.LookAt(new Vector3(0,1,0));preview.camera.fieldOfView=42;preview.camera.nearClipPlane=.05f;preview.camera.farClipPlane=30;preview.lights[0].intensity=1.6f;preview.lights[0].transform.rotation=Quaternion.Euler(35,210,0);preview.lights[1].intensity=1;
foreach(var clip in new[]{set.Combo1,set.Combo2,set.Combo3,set.Combo4,set.RunningAttack}){if(!clip)continue;bool running=clip==set.RunningAttack;controller.SetFloat("Speed",running?5.3f:0);var action=AnimationClipPlayable.Create(graph,clip);action.SetApplyFootIK(false);graph.Connect(action,0,layers,1);layers.SetInputWeight(1,1);if(running&&!set.OriginalDownloadedPlayback)layers.SetLayerMaskFromAvatarMask(1,mask);else{var full=new AvatarMask();for(int i=0;i<(int)AvatarMaskBodyPart.LastBodyPart;i++)full.SetHumanoidBodyPartActive((AvatarMaskBodyPart)i,true);layers.SetLayerMaskFromAvatarMask(1,full);}
Vector3 local=Vector3.zero;Quaternion rot=Quaternion.identity;float max=0;var foot=animator.GetBoneTransform(HumanBodyBones.LeftFoot);Vector3 last=foot.position;float feet=0;
for(int i=0;i<30;i++){action.SetTime(clip.length*i/30f);graph.Evaluate(1f/60);fit.Invoke(weapon,args);if(i==0){local=model.transform.localPosition;rot=model.transform.localRotation;}max=Mathf.Max(max,Vector3.Distance(local,model.transform.localPosition));if(Quaternion.Angle(rot,model.transform.localRotation)>.01f)throw new Exception("Sword grip rotation drift");feet+=Vector3.Distance(last,foot.position);last=foot.position;if(i==14)FitSwordShoulder.Capture(preview,"Logs/"+clip.name+"-preview.png",clone);}
if(max>.0001f)throw new Exception("Sword detached from hand");if(running&&feet<.1f)throw new Exception("Running legs static");report.AppendLine(clip.name+": fixed palm grip drift="+max+"m; foot motion="+feet+"m");layers.DisconnectInput(1);graph.DestroyPlayable(action);}
File.WriteAllText("Logs/DownloadedSword-preview-check.txt",report.ToString());Debug.Log("DOWNLOADED_SWORD_PREVIEW_OK");
}finally{if(graph.IsValid())graph.Destroy();preview.Cleanup();}}
}}
#endif


